// =====================================================
// SOLUCIONES COLINA — Pantalla de Login con PIN
// Soporta acceso local instantáneo y sincronización con Firebase en la Nube
// =====================================================
import React, { useState, useRef, useEffect } from 'react'
import { verificarPin } from '../services/authService'
import { obtenerPinHash, cargarPerfil, type PerfilEmpresa } from '../services/localStorageService'
import { iniciarSesionNube } from '../services/cloudSyncService'
import { GoldenParticlesLogo } from '../components/GoldenParticlesLogo'

interface LoginScreenProps {
  onAutenticado: (sal: string, pin: string) => void
  onIrARegistro: () => void
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ onAutenticado, onIrARegistro }) => {
  const [pin, setPin] = useState('')
  const [error, setError] = useState('')
  const [cargando, setCargando] = useState(false)
  const [intentos, setIntentos] = useState(0)
  const [tieneCuentaGuardada, setTieneCuentaGuardada] = useState<boolean | null>(null)
  const [nombreEmpresaLocal, setNombreEmpresaLocal] = useState<string>('')
  
  // Modo de ingreso: PIN directo si hay cuenta en este navegador, o NIT/Correo desde Firebase
  const [modoNube, setModoNube] = useState(false)
  const [identificadorNube, setIdentificadorNube] = useState('')
  const [pinNube, setPinNube] = useState('')

  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    // Verificar si ya existe una cuenta guardada en este dispositivo
    obtenerPinHash().then(async hash => {
      if (hash) {
        setTieneCuentaGuardada(true)
        setModoNube(false)
        setTimeout(() => inputRef.current?.focus(), 300)
      } else {
        setTieneCuentaGuardada(false)
        setModoNube(true)
      }
    }).catch(() => {
      setTieneCuentaGuardada(false)
      setModoNube(true)
    })
  }, [])

  const handlePinChange = async (valor: string) => {
    const limpio = valor.replace(/\D/g, '').slice(0, 6)
    setPin(limpio)
    setError('')

    // Auto-verificar cuando llega a 6 dígitos
    if (limpio.length === 6) {
      await verificarLocal(limpio)
    }
  }

  const verificarLocal = async (pinIngresado: string) => {
    setCargando(true)
    try {
      const sal = await verificarPin(pinIngresado)
      if (sal) {
        onAutenticado(sal, pinIngresado)
      } else {
        const nuevosIntentos = intentos + 1
        setIntentos(nuevosIntentos)
        setPin('')
        setError(
          nuevosIntentos >= 3
            ? `PIN incorrecto. ${5 - nuevosIntentos} intentos restantes.`
            : 'PIN incorrecto. Intenta de nuevo.'
        )
        inputRef.current?.focus()
      }
    } catch {
      setError('Error al verificar PIN. Intenta de nuevo.')
      setPin('')
    } finally {
      setCargando(false)
    }
  }

  const handleLoginNube = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!identificadorNube.trim()) {
      setError('Ingresa tu NIT o correo electrónico')
      return
    }
    if (pinNube.length !== 6) {
      setError('El PIN debe tener 6 dígitos numéricos')
      return
    }

    setCargando(true)
    setError('')

    try {
      const res = await iniciarSesionNube(identificadorNube, pinNube)
      if (res && res.sal) {
        onAutenticado(res.sal, pinNube)
      } else {
        setError('No se pudo verificar la cuenta. Revisa tus datos.')
      }
    } catch (err: any) {
      setError(err?.message || 'Error al conectar con la nube.')
    } finally {
      setCargando(false)
    }
  }

  // Bloqueo temporal tras 5 intentos fallidos en PIN local
  const bloqueado = intentos >= 5

  return (
    <div className="auth-root">
      <div className="auth-card">
        <GoldenParticlesLogo size={48} mostrarAura={true} />
        <h1 className="auth-titulo font-serif">Soluciones Colina</h1>
        <p className="auth-sub">
          {modoNube ? 'Sincroniza y abre tu cuenta desde la nube' : 'Ingresa tu PIN para continuar'}
        </p>

        {/* Selector de modo: Iniciar sesión o Crear cuenta */}
        <div className="auth-switcher">
          <button
            type="button"
            className="auth-switch-btn activo"
          >
            Iniciar sesión
          </button>
          <button
            type="button"
            className="auth-switch-btn"
            onClick={onIrARegistro}
          >
            Crear cuenta
          </button>
        </div>

        {error && <div className="auth-error">{error}</div>}

        {/* ── MODO 1: SINCRONIZACIÓN EN LA NUBE (NIT o Correo + PIN) ── */}
        {modoNube ? (
          <form className="auth-form login-nube-form" onSubmit={handleLoginNube}>
            <div className="campo-grupo">
              <label className="campo-label">NIT o Correo Electrónico *</label>
              <input
                className="campo-input"
                type="text"
                placeholder="Ej: 100120471 o empresa@correo.com"
                value={identificadorNube}
                onChange={e => setIdentificadorNube(e.target.value)}
                autoComplete="username"
                disabled={cargando}
              />
            </div>

            <div className="campo-grupo">
              <label className="campo-label">PIN de 6 dígitos *</label>
              <input
                className="campo-input pin-input"
                type="password"
                inputMode="numeric"
                maxLength={6}
                placeholder="••••••"
                value={pinNube}
                onChange={e => setPinNube(e.target.value.replace(/\D/g, '').slice(0, 6))}
                disabled={cargando}
                autoComplete="current-password"
              />
            </div>

            <button
              type="submit"
              className="btn-auth-primario"
              disabled={cargando}
            >
              {cargando ? 'Verificando en la nube...' : 'Entrar a mi cuenta →'}
            </button>

            {tieneCuentaGuardada && (
              <button
                type="button"
                className="login-modo-toggle"
                onClick={() => { setModoNube(false); setError(''); }}
              >
                ← Usar PIN directo en este equipo
              </button>
            )}
          </form>
        ) : (
          /* ── MODO 2: PIN DIRECTO EN EQUIPO RECONOCIDO ── */
          bloqueado ? (
            <div className="auth-bloqueado">
              🔒 Acceso bloqueado por múltiples intentos fallidos.
              <br />Reinicia la app e intenta de nuevo.
            </div>
          ) : (
            <div className="auth-form">
              {/* Indicador visual del PIN */}
              <div className="pin-dots-row" onClick={() => inputRef.current?.focus()}>
                {Array.from({ length: 6 }).map((_, i) => (
                  <div
                    key={i}
                    className={`pin-dot ${i < pin.length ? 'lleno' : ''} ${error && i < pin.length ? 'error' : ''}`}
                  />
                ))}
              </div>

              {/* Input oculto para capturar el PIN */}
              <input
                ref={inputRef}
                className="pin-input-oculto"
                type="password"
                inputMode="numeric"
                maxLength={6}
                value={pin}
                onChange={e => handlePinChange(e.target.value)}
                disabled={cargando || bloqueado}
                autoComplete="current-password"
              />

              {cargando && <div className="auth-cargando">Verificando...</div>}

              <p className="pin-hint">
                Toca los puntos y escribe tu PIN de 6 dígitos
              </p>

              <button
                type="button"
                className="login-modo-toggle"
                onClick={() => { setModoNube(true); setError(''); }}
              >
                ¿Ingresar con otra cuenta o restaurar desde la nube?
              </button>
            </div>
          )
        )}

        {/* Enlace inferior para crear cuenta */}
        <div className="auth-footer-switch">
          <span>¿No tienes una cuenta aún?</span>
          <button
            type="button"
            className="auth-link-btn"
            onClick={onIrARegistro}
          >
            Crear cuenta / Registrarse →
          </button>
        </div>
      </div>
    </div>
  )
}
