// SOLUCIONES COLINA — Servicio de Sincronización en la Nube
// Almacena y administra cuentas y perfiles en Firebase Firestore
// Los datos privados se mantienen protegidos con cifrado Zero-Knowledge
// =====================================================
import { doc, getDoc, setDoc, collection, query, where, getDocs } from 'firebase/firestore'
import { db } from '../firebase'
import { hashPin } from './encryptionService'
import {
  guardarPin,
  guardarPerfil,
  iniciarSesion,
  marcarInstalado,
  type PerfilEmpresa
} from './localStorageService'

export interface CuentaNubeResultado {
  perfil: PerfilEmpresa
  pinHash: string
  pinSal: string
}

/**
 * Guarda o actualiza el perfil del negocio en Firebase Firestore
 */
export async function sincronizarPerfilNube(
  perfil: PerfilEmpresa,
  pinHash: string,
  pinSal: string
): Promise<boolean> {
  if (!import.meta.env.VITE_FIREBASE_PROJECT_ID) {
    console.warn('[Soluciones Colina] Firebase no configurado en entorno.')
    return false
  }

  try {
    const nitLimpio = perfil.nit.replace(/\D/g, '')
    const docId = nitLimpio || perfil.id
    const docRef = doc(db, 'negocios', docId)

    const data = {
      id: docId,
      perfilId: perfil.id,
      nombre: perfil.nombre,
      razonSocial: perfil.nombre,
      nit: perfil.nit,
      dv: perfil.dv,
      correo: perfil.correo.toLowerCase().trim(),
      telefono: perfil.telefono || '',
      direccion: perfil.direccion || '',
      ciudad: perfil.ciudad || '',
      creadoEn: perfil.creadoEn || new Date().toISOString(),
      actualizadoEn: new Date().toISOString(),
      pinHash,
      pinSal,
      sistema: 'Soluciones Colina',
      origen: 'web-escritorio'
    }

    await setDoc(docRef, data, { merge: true })
    console.log('[Soluciones Colina] Perfil sincronizado exitosamente en la nube:', docId)
    return true
  } catch (err) {
    console.warn('[Soluciones Colina] No se pudo sincronizar perfil en Firebase:', err)
    return false
  }
}

/**
 * Busca una cuenta en Firebase Firestore por NIT o Correo Electrónico
 */
export async function buscarCuentaNube(identificador: string): Promise<CuentaNubeResultado | null> {
  if (!import.meta.env.VITE_FIREBASE_PROJECT_ID) {
    return null
  }

  const limpio = identificador.trim()
  const nitLimpio = limpio.replace(/\D/g, '')
  const correoLimpio = limpio.toLowerCase()

  try {
    // 1. Intento por ID directo de NIT
    if (nitLimpio) {
      const docRef = doc(db, 'negocios', nitLimpio)
      const snap = await getDoc(docRef)
      if (snap.exists()) {
        const d = snap.data()
        return formatearResultadoNube(d)
      }
    }

    // 2. Consulta por campo 'correo'
    if (correoLimpio.includes('@')) {
      const qCorreo = query(collection(db, 'negocios'), where('correo', '==', correoLimpio))
      const snapCorreo = await getDocs(qCorreo)
      if (!snapCorreo.empty) {
        const d = snapCorreo.docs[0].data()
        return formatearResultadoNube(d)
      }
    }

    // 3. Consulta por campo 'nit'
    if (nitLimpio) {
      const qNit = query(collection(db, 'negocios'), where('nit', '==', nitLimpio))
      const snapNit = await getDocs(qNit)
      if (!snapNit.empty) {
        const d = snapNit.docs[0].data()
        return formatearResultadoNube(d)
      }
    }

    return null
  } catch (err) {
    console.warn('[Soluciones Colina] Error al buscar cuenta en la nube:', err)
    return null
  }
}

function formatearResultadoNube(d: Record<string, any>): CuentaNubeResultado {
  const perfil: PerfilEmpresa = {
    id: d.id || d.perfilId || crypto.randomUUID(),
    nombre: d.nombre || d.razonSocial || 'Mi Empresa',
    nit: d.nit || '',
    dv: d.dv || '',
    correo: d.correo || '',
    telefono: d.telefono || '',
    direccion: d.direccion || '',
    ciudad: d.ciudad || '',
    creadoEn: d.creadoEn || new Date().toISOString()
  }

  return {
    perfil,
    pinHash: d.pinHash || '',
    pinSal: d.pinSal || ''
  }
}

/**
 * Inicia sesión verificando credenciales contra la nube Firebase y restaura el perfil en este dispositivo
 */
export async function iniciarSesionNube(
  identificador: string,
  pinIngresado: string
): Promise<{ sal: string; perfil: PerfilEmpresa } | null> {
  const cuenta = await buscarCuentaNube(identificador)
  if (!cuenta) {
    throw new Error('No se encontró ninguna cuenta registrada con este NIT o correo en la nube.')
  }

  if (!cuenta.pinHash || !cuenta.pinSal) {
    throw new Error('La cuenta encontrada no tiene un PIN configurado.')
  }

  const hashCalculado = await hashPin(pinIngresado, cuenta.pinSal)
  if (hashCalculado !== cuenta.pinHash) {
    throw new Error('PIN incorrecto para esta cuenta.')
  }

  // Guardar en este dispositivo para acceso local ultrarrápido
  await guardarPin(cuenta.pinHash, cuenta.pinSal)
  await guardarPerfil(cuenta.perfil, pinIngresado, cuenta.pinSal)
  await marcarInstalado()
  await iniciarSesion(cuenta.pinHash)

  return {
    sal: cuenta.pinSal,
    perfil: cuenta.perfil
  }
}
